// ASTRA: private, offline fitness journal. Data lives only in this browser (IndexedDB).
const DB='orrery',ST1=['workouts','prs','nutrition','hydration','measurements'],ST=[...ST1,'days'];
const LIB=['Squat','Bench Press','Deadlift','Hip Thrust','Lat Pulldown','Shoulder Press','Bicep Curl','Leg Press','Pull-up','Barbell Row'];
const MEAS=['Weight','Bust','Waist','Abdomen','Hips','Left arm','Right arm','Left thigh','Right thigh','Calf'];
const TYPES={strength:'Strength',cardio:'Cardio',recovery:'Active recovery'};
const FACTS=['Sunlight takes about 8 minutes and 20 seconds to reach Earth.','The Moon drifts away from Earth by roughly 3.8 cm each year.','Adult bodies are roughly 50 to 65 percent water by mass.','Muscle protein synthesis stays raised for around a day or two after resistance training.','Bone is living tissue: it remodels throughout adult life.','The fastest known pulsar spins about 716 times per second.'];
let db,D={},draft=null,fday=null,T={left:90,set:90,id:null};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const iso=d=>new Date(d.getTime()-d.getTimezoneOffset()*6e4).toISOString().slice(0,10);
const today=()=>iso(new Date());
const addDays=(s,n)=>{const d=new Date(s+'T12:00');d.setDate(d.getDate()+n);return iso(d)};
const gap=(a,b)=>Math.round((new Date(a+'T12:00')-new Date(b+'T12:00'))/864e5);
const sum=(a,k)=>a.reduce((s,x)=>s+(+x[k]||0),0);
const e1=(w,r)=>r<=1?w:w*(1+r/30); // Epley estimate: approximate, least reliable above ~12 reps
const fmt=s=>Math.floor(s/60)+':'+String(s%60).padStart(2,'0');
const req=r=>new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});
const tx=(s,m='readonly')=>db.transaction(s,m).objectStore(s);
const all=s=>req(tx(s).getAll()),put=(s,v)=>req(tx(s,'readwrite').put(v)),rm=(s,id)=>req(tx(s,'readwrite').delete(id));
const open=()=>new Promise((ok,no)=>{const r=indexedDB.open(DB,3);r.onupgradeneeded=e=>{const d=r.result;if(e.oldVersion<1){d.createObjectStore('profile',{keyPath:'k'});ST1.forEach(s=>d.createObjectStore(s,{keyPath:'id',autoIncrement:true}))}if(e.oldVersion<2)d.createObjectStore('days',{keyPath:'date'});if(e.oldVersion<3)d.createObjectStore('photos',{keyPath:'id',autoIncrement:true});};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});
async function load(){for(const s of ST)D[s]=await all(s);D.me=await req(tx('profile').get('me'))||{k:'me',name:'',water:2000,kcal:0,protein:0};D.n=await req(tx('profile').get('notif'))||ASTRA.defaults();D.photos=await all('photos')}
const day=(s,d)=>D[s].filter(x=>x.date===d);
const wat=d=>sum(day('hydration',d).filter(x=>x.bev==='Water'),'ml');
const vol=w=>(w.ex||[]).reduce((a,e)=>a+e.sets.filter(s=>!s.wu).reduce((b,s)=>b+s.w*s.r,0),0); // warm-ups excluded
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('on'),2600)}
const bar=(v,m)=>`<div class="bar"><i style="width:${m?Math.min(100,v/m*100):0}%"></i></div>`;
const ring=(v,m,l,s)=>{const r=44,c=2*Math.PI*r,p=Math.min(1,m?v/m:0);return `<svg class="ring" viewBox="0 0 100 100"><circle cx="50" cy="50" r="${r}" class="rt"/><circle cx="50" cy="50" r="${r}" class="rp" stroke-dasharray="${c*p} ${c}" transform="rotate(-90 50 50)"/><text x="50" y="52" text-anchor="middle" class="rl">${l}</text><text x="50" y="66" text-anchor="middle" class="rs">${s}</text></svg>`};
const spark=v=>{if(v.length<2)return '<span class="muted">1 point</span>';const mn=Math.min(...v),mx=Math.max(...v),g=mx-mn||1;return `<svg class="sp" viewBox="0 0 100 30" preserveAspectRatio="none"><polyline points="${v.map((y,i)=>`${i/(v.length-1)*100},${28-(y-mn)/g*24}`).join(' ')}"/></svg>`};
function heat(){const a={},rk={strength:3,cardio:2,recovery:1};D.workouts.forEach(w=>{if(!a[w.date]||rk[w.type]>rk[a[w.date]])a[w.date]=w.type});const t=today(),dow=(new Date(t+'T12:00').getDay()+6)%7,s=addDays(t,-dow-77);let h='';for(let i=0;i<84;i++){const d=addDays(s,i);h+=`<i class="c ${d>t?'f':a[d]||''}" title="${d}"></i>`}return `<div class="heat">${h}</div>`}
// Streak: counts active days; up to 2 rest days between sessions never break it.
function streak(){const ds=[...new Set(D.workouts.map(w=>w.date))].sort().reverse();if(!ds.length||gap(today(),ds[0])>3)return 0;let n=1;for(let i=1;i<ds.length;i++){if(gap(ds[i-1],ds[i])<=3)n++;else break}return n}
function last(n){n=n.trim().toLowerCase();if(!n)return '';const w=[...D.workouts].sort((a,b)=>b.date.localeCompare(a.date)).find(w=>(w.ex||[]).some(e=>e.name.toLowerCase()===n));if(!w)return '';const e=w.ex.find(e=>e.name.toLowerCase()===n);return 'Last time ('+w.date+'): '+e.sets.filter(s=>!s.wu).map(s=>s.w+' kg × '+s.r).join(', ')}
const blank=()=>({name:'',type:'strength',date:today(),dur:'',dist:'',rpe:'',notes:'',ex:[{name:'',sets:[{w:'',r:'',wu:false}]}]});
function form(){const d=draft;return `<section class="card"><h2>${d.id?'Edit':'New'} session</h2>
<div class="row"><input data-f="name" placeholder="Name, e.g. Push day" value="${esc(d.name)}"><select data-f="type">${Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${d.type===k?'selected':''}>${v}</option>`).join('')}</select></div>
<div class="row"><input type="date" data-f="date" value="${d.date}"><input type="number" data-f="dur" placeholder="Minutes" value="${d.dur}"><input type="number" min="1" max="10" data-f="rpe" placeholder="RPE 1–10" value="${d.rpe}"></div>
${d.type==='cardio'?`<input type="number" step="0.01" data-f="dist" placeholder="Distance (km)" value="${d.dist}">`:''}
${d.type==='strength'?d.ex.map((e,i)=>`<div class="ex"><div class="row"><input data-e="${i}" data-f="name" list="exl" placeholder="Exercise" value="${esc(e.name)}"><button class="x" data-act="rmex" data-i="${i}" aria-label="Remove exercise">×</button></div><small id="h${i}">${esc(last(e.name))}</small>
${e.sets.map((s,j)=>`<div class="row set"><span>${j+1}</span><input type="number" step="0.5" data-e="${i}" data-s="${j}" data-f="w" placeholder="kg" value="${s.w}"><input type="number" data-e="${i}" data-s="${j}" data-f="r" placeholder="reps" value="${s.r}"><label class="wu"><input type="checkbox" data-e="${i}" data-s="${j}" data-f="wu" ${s.wu?'checked':''}>warm-up</label><button class="x" data-act="rmset" data-i="${i}" data-j="${j}" aria-label="Remove set">×</button></div>`).join('')}
<div class="row"><button class="btn sm" data-act="addset" data-i="${i}">+ Set</button><button class="btn sm" data-act="dup" data-i="${i}">Duplicate</button></div></div>`).join('')+'<button class="btn" data-act="addex">+ Exercise</button>':''}
<textarea data-f="notes" placeholder="Notes: how it felt, what to change next time">${esc(d.notes)}</textarea>
<div class="row"><button class="btn fill" data-act="save">Save session</button><button class="btn" data-act="cancel">Cancel</button></div></section>`}
const V={
home(){const t=today(),h=new Date().getHours(),wk=D.workouts.filter(w=>w.date>addDays(t,-7)&&w.type!=='recovery').length,n=day('nutrition',t),w=wat(t),tg=D.me.water||2000,td=day('workouts',t);
const msg=!D.workouts.length?'Your first observation is the hardest. Log a session when you are ready.':wk===0?'A quiet week so far. Rest is part of the experiment.':wk<3?`${wk} session${wk>1?'s':''} this week. A steady orbit.`:`${wk} sessions this week. Protect your recovery.`;
return `<p class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'})}</p><h1>${h<12?'Good morning':h<18?'Good afternoon':'Good evening'}${D.me.name?', '+esc(D.me.name):''}</h1><p class="muted">${msg}</p>
<section class="card"><div class="row around">${ring(w,tg,w+' ml','of '+tg)}<div class="grow"><p class="eyebrow">Today</p><p>${td.length?td.map(x=>esc(x.name)).join(', ')+' logged':'No session logged yet'}</p><p class="muted">${sum(n,'kcal')} kcal and ${sum(n,'p')} g protein logged</p><button class="btn sm" data-act="addw" data-ml="250">+250 ml water</button></div></div></section>
<section class="card"><h2>Activity, last 12 weeks</h2>${heat()}<p class="legend"><i class="c strength"></i>Strength <i class="c cardio"></i>Cardio <i class="c recovery"></i>Recovery. Empty days are rest, never failure.</p>
<div class="stats"><div><b>${streak()}</b><small>active streak</small></div><div><b>${D.workouts.length}</b><small>sessions</small></div><div><b>${D.prs.length}</b><small>records set</small></div></div></section>
<div class="row"><a class="btn fill" href="#train" data-act="new">Log workout</a><a class="btn" href="#fuel">Log food</a><a class="btn" href="#days" data-act="open" data-d="${t}">Daily summary</a></div>
<p class="fact">${FACTS[Math.floor(Date.now()/864e5)%FACTS.length]}</p>`},
train(){const hist=[...D.workouts].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id).slice(0,25),g={};D.prs.forEach(p=>(g[p.ex]??=[]).push(p));
return `<h1>Training</h1>
<section class="card"><p class="eyebrow">Rest timer</p><div class="tm" id="tm">${fmt(T.left)}</div><div class="row">${[60,90,120,180].map(s=>`<button class="btn sm" data-act="preset" data-s="${s}">${s}s</button>`).join('')}</div><div class="row"><button class="btn fill" data-act="tgo">${T.id?'Pause':'Start'}</button><button class="btn" data-act="treset">Reset</button></div></section>
<datalist id="exl">${[...new Set([...LIB,...D.workouts.flatMap(w=>(w.ex||[]).map(e=>e.name))])].map(n=>`<option value="${esc(n)}">`).join('')}</datalist>
${draft?form():'<button class="btn fill wide" data-act="new">+ New session</button>'}
<h2>Records</h2>${Object.entries(g).map(([n,a])=>{a.sort((x,y)=>x.date.localeCompare(y.date)||x.e1rm-y.e1rm);const b=a.at(-1);return `<div class="li"><div><b>${esc(n)}</b><small>${b.w} kg × ${b.r}, estimated 1RM ${b.e1rm} kg, ${b.date}</small></div>${spark(a.map(x=>x.e1rm))}</div>`}).join('')||'<p class="muted">Records appear once you log working sets with weight and reps. Each exercise is tracked on its own.</p>'}
<h2>History</h2>${hist.map(w=>`<div class="li"><div><b>${esc(w.name)}</b><small>${w.date}, ${TYPES[w.type]}${w.dur?', '+w.dur+' min':''}${w.dist?', '+w.dist+' km':''}${vol(w)?', '+Math.round(vol(w))+' kg working volume':''}</small></div><button class="btn sm" data-act="repeat" data-id="${w.id}">Repeat</button><button class="x" data-act="delw" data-id="${w.id}" aria-label="Delete">×</button></div>`).join('')||'<p class="muted">No sessions yet.</p>'}`},
water(){const t=today(),tg=D.me.water||2000,ds=[...Array(7)].map((_,i)=>addDays(t,i-6)),vs=ds.map(wat),lg=vs.filter(v=>v>0),es=day('hydration',t);
return `<h1>Hydration</h1><section class="card"><div class="row around">${ring(wat(t),tg,wat(t)+' ml','of '+tg)}<div class="grow"><p class="muted">Only plain water fills the ring. Other drinks are listed but not counted as water.</p></div></div>
<div class="row">${[150,250,330,500].map(m=>`<button class="btn" data-act="addw" data-ml="${m}">${m} ml</button>`).join('')}</div>
<div class="row"><select id="bev">${['Water','Coffee','Tea','Milk','Other'].map(b=>`<option>${b}</option>`).join('')}</select><input id="cml" type="number" placeholder="Custom ml"><button class="btn fill" data-act="cw">Add</button></div></section>
<section class="card"><h2>Last 7 days</h2><div class="bars">${ds.map((d,i)=>`<div class="b"><i style="height:${Math.min(100,vs[i]/tg*100)}%"></i><small>${d.slice(8)}</small></div>`).join('')}</div>
<p class="muted">${lg.length?`Average on logged days: ${Math.round(lg.reduce((a,b)=>a+b)/lg.length)} ml. Reached your own target on ${vs.filter(v=>v>=tg).length} of 7 days.`:'Nothing logged this week yet.'}</p></section>
<h2>Today's entries</h2>${es.map(x=>`<div class="li"><div><b>${x.bev}</b> ${x.ml} ml</div><button class="x" data-act="delh" data-id="${x.id}" aria-label="Delete">×</button></div>`).join('')||'<p class="muted">Tap a button above to log your first drink.</p>'}<p class="muted">Your target is set in Vault. There is no single right number for everyone.</p>`},
fuel(){const t=fday,ms=day('nutrition',t),K=sum(ms,'kcal'),P=sum(ms,'p'),me=D.me,wk=[...Array(7)].map((_,i)=>sum(day('nutrition',addDays(today(),-i)),'kcal')).filter(Boolean);
return `<h1>Fuel</h1><p class="muted">Manual and approximate. A higher or lower day is data, not a verdict.</p><input type="date" id="fd" value="${t}">
<section class="card"><div class="stats"><div><b>${K}</b><small>kcal${me.kcal?' of '+me.kcal:''}</small></div><div><b>${P}</b><small>protein g${me.protein?' of '+me.protein:''}</small></div><div><b>${sum(ms,'c')}</b><small>carbs g</small></div><div><b>${sum(ms,'f')}</b><small>fat g</small></div></div>${me.kcal?bar(K,me.kcal):''}${me.protein?bar(P,me.protein):''}</section>
<section class="card"><h2>Add a meal</h2><input id="ml" placeholder="Meal name (optional)"><div class="row"><input id="mk" type="number" placeholder="kcal"><input id="mp" type="number" placeholder="Protein g"><input id="mc" type="number" placeholder="Carbs g"><input id="mf" type="number" placeholder="Fat g"></div><div class="row"><button class="btn fill" data-act="addmeal">Add meal</button><button class="btn" data-act="copyy">Copy previous day</button></div></section>
${ms.map(m=>`<div class="li"><div><b>${esc(m.label)}</b><small>${m.kcal} kcal, P ${m.p}, C ${m.c}, F ${m.f}</small></div><button class="x" data-act="delmeal" data-id="${m.id}" aria-label="Delete">×</button></div>`).join('')}
<p class="muted">${wk.length?`Average on logged days this week: ${Math.round(wk.reduce((a,b)=>a+b)/wk.length)} kcal (${wk.length} days).`:''}</p>`},
vault(){const me=D.me;return `<h1>Vault</h1><section class="card"><h2>Preferences</h2><input data-p="name" placeholder="Your name" value="${esc(me.name)}"><div class="row"><input data-p="water" type="number" placeholder="Water target ml" value="${me.water||''}"><input data-p="kcal" type="number" placeholder="Calorie target (optional)" value="${me.kcal||''}"><input data-p="protein" type="number" placeholder="Protein g (optional)" value="${me.protein||''}"></div></section>
<section class="card"><h2>Backup</h2><p class="muted">Everything is stored only in this browser. Clearing site data, uninstalling or losing the device deletes it. Export a backup regularly and keep it somewhere safe.</p><button class="btn fill" data-act="exp">Export full backup (JSON)</button><button class="btn" data-act="expcsv">Export workouts (CSV)</button><label class="btn">Restore from backup<input id="imp" type="file" accept="application/json" hidden></label><button class="btn" data-act="clear">Erase all data</button></section>
<section class="card"><h2>Reminders</h2><p class="muted">Notifications, quiet hours and schedules.</p><a class="btn" href="#remind">Notification settings</a></section><section class="card"><h2>Privacy</h2><p class="muted">No accounts, no servers, no tracking. Nothing you enter leaves this device. This is a general tracking tool, not medical advice; calorie and 1RM figures are estimates.</p></section>`}};
function render(){const r=(location.hash||'#home').slice(1),k=V[r]?r:'home';$('#view').innerHTML=V[k]();document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('on',a.getAttribute('href')==='#'+(k==='remind'?'vault':k)))}
function tick(){T.left--;const e=$('#tm');if(e)e.textContent=fmt(Math.max(0,T.left));if(T.left<=0){clearInterval(T.id);T.id=null;toast('Rest complete');navigator.vibrate?.(300);try{const a=new AudioContext(),o=a.createOscillator();o.connect(a.destination);o.frequency.value=660;o.start();o.stop(a.currentTime+.4)}catch{}render()}}
async function save(){const d=draft;d.ex=d.type==='strength'?d.ex.map(e=>({name:e.name.trim(),sets:e.sets.filter(s=>s.r!==''||s.w!=='').map(s=>({w:+s.w||0,r:+s.r||0,wu:!!s.wu}))})).filter(e=>e.name&&e.sets.length):[];
if(d.type==='strength'&&!d.ex.length)return toast('Add at least one exercise with a set');
d.name=d.name.trim()||TYPES[d.type];d.dur=+d.dur||0;d.dist=+d.dist||0;d.rpe=+d.rpe||0;
const beaten=[];for(const e of d.ex){const ws=e.sets.filter(s=>!s.wu&&s.r>0&&s.w>0);if(!ws.length)continue;const b=Math.max(...ws.map(s=>e1(s.w,s.r))),prev=Math.max(0,...D.prs.filter(p=>p.ex.toLowerCase()===e.name.toLowerCase()).map(p=>p.e1rm));if(b>prev){const s=ws.find(s=>e1(s.w,s.r)===b);await put('prs',{ex:e.name,e1rm:+b.toFixed(1),w:s.w,r:s.r,date:d.date});if(prev>0)beaten.push(e.name)}}
await put('workouts',d);draft=null;await load();toast(beaten.length?'New personal record: '+beaten.join(', '):'Session saved');notifyAch(beaten)}
const wipe=async(p=true)=>{for(const s of [...ST,'profile',...(p?['photos']:[])])await req(tx(s,'readwrite').clear())};
function dl(n,t,ty){const a=document.createElement('a');a.href=URL.createObjectURL(t instanceof Blob?t:new Blob([t],{type:ty}));a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1e3)}
async function imp(f){try{const j=JSON.parse(await f.text());if(j.app!=='orrery'||!ST.every(s=>s==='days'||Array.isArray(j[s])))throw 0;if(!confirm('Restoring replaces everything currently in the app. Export a backup first if unsure. Continue?'))return;await wipe(false);for(const s of ST)for(const r of (j[s]||[]))await put(s,r);if(j.me?.k)await put('profile',j.me);if(j.n?.k)await put('profile',j.n);await load();render();toast('Backup restored')}catch{toast('That file is not a valid ASTRA backup')}}
const I=b=>+b.dataset.i,ID=b=>+b.dataset.id,N=id=>$(id).value;
const addH=async(ml,bev)=>{await put('hydration',{date:today(),ml,bev:bev||'Water'});await load()};
const A={new:()=>{draft=blank()},cancel:()=>{draft=null},addex:()=>draft.ex.push({name:'',sets:[{w:'',r:'',wu:false}]}),rmex:b=>draft.ex.splice(I(b),1),
addset:b=>{const s=draft.ex[I(b)].sets;s.push({...(s.at(-1)||{w:'',r:''}),wu:false})},rmset:b=>draft.ex[I(b)].sets.splice(+b.dataset.j,1),dup:b=>draft.ex.splice(I(b)+1,0,structuredClone(draft.ex[I(b)])),save,
repeat:b=>{const{id,...r}=structuredClone(D.workouts.find(x=>x.id===ID(b)));draft={...r,date:today()};toast('Loaded. Adjust and save.')},
delw:async b=>{if(confirm('Delete this session?')){await rm('workouts',ID(b));await load()}},
preset:b=>{clearInterval(T.id);T.id=null;T.left=T.set=+b.dataset.s},treset:()=>{clearInterval(T.id);T.id=null;T.left=T.set},tgo:()=>{if(T.id){clearInterval(T.id);T.id=null}else if(T.left>0)T.id=setInterval(tick,1e3)},
addw:b=>addH(+b.dataset.ml),cw:async()=>{const v=+N('#cml');if(v>0&&v<=5000){await addH(v,N('#bev'));toast('Added')}else toast('Enter an amount from 1 to 5000 ml')},delh:async b=>{await rm('hydration',ID(b));await load()},
addmeal:async()=>{const g=k=>+N('#m'+k)||0;if(!g('k')&&!g('p')&&!g('c')&&!g('f'))return toast('Enter at least one value');await put('nutrition',{date:fday,label:N('#ml').trim()||'Meal',kcal:g('k'),p:g('p'),c:g('c'),f:g('f')});await load()},
delmeal:async b=>{await rm('nutrition',ID(b));await load()},
copyy:async()=>{const p=day('nutrition',addDays(fday,-1));if(!p.length)return toast('Nothing logged the day before');for(const m of p){const{id,...r}=m;await put('nutrition',{...r,date:fday})}await load()},
addm:async()=>{const m=N('#mm').trim(),v=+N('#mv');if(!m||!(v>0))return toast('Choose a measurement and enter a value');await put('measurements',{date:N('#md')||today(),m,v});await load()},
delm:async b=>{await rm('measurements',ID(b));await load()},
exp:()=>dl(`orrery-backup-${today()}.json`,JSON.stringify({app:'orrery',v:1,me:D.me,n:D.n,...Object.fromEntries(ST.map(s=>[s,D[s]]))}),'application/json'),
expcsv:()=>{const r=[['date','session','type','exercise','set','kg','reps','warmup']];D.workouts.forEach(w=>{if(w.ex?.length)w.ex.forEach(e=>e.sets.forEach((s,i)=>r.push([w.date,w.name,w.type,e.name,i+1,s.w,s.r,s.wu?1:0])));else r.push([w.date,w.name,w.type,'','','','',''])});dl('workouts.csv',r.map(x=>x.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n'),'text/csv')},
clear:async()=>{if(confirm('Erase ALL data on this device? This cannot be undone. Export a backup first.')){await wipe();await load();toast('All data erased')}}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b||!A[b.dataset.act])return;await A[b.dataset.act](b);render()});
document.addEventListener('input',e=>{const t=e.target,f=t.dataset.f;if(!f||!draft)return;const v=t.type==='checkbox'?t.checked:t.value;if(t.dataset.e!==undefined){const x=draft.ex[+t.dataset.e];if(t.dataset.s!==undefined)x.sets[+t.dataset.s][f]=v;else{x[f]=v;const h=$('#h'+t.dataset.e);if(h)h.textContent=last(v)}}else{draft[f]=v;if(f==='type')render()}});
