const NOTE='<p class="muted">Changes are shown without judgment. Tape measurements vary with hydration, time of day, digestion, cycle, posture and technique, so differences of around 1 cm or 1 percent are often within normal variation. Read them alongside strength, energy and how you feel, never on their own.</p>';
const HOWTO='<section class="card"><h2>Measuring consistently</h2><ul class="tips"><li>Measure at the same time of day, ideally in the morning before eating, in similar conditions each week.</li><li>Use the same landmarks every time, for example waist at its narrowest point or at navel level, hips at the widest point, arm and thigh at the midpoint. Pick your spots and keep them.</li><li>Stand relaxed. Keep the tape snug, level with the floor and not squeezing. Measure twice and enter the average.</li><li>Record left and right sides separately.</li></ul></section>';
function chart(a){if(a.length<2)return '<p class="muted">Two or more entries are needed for a chart.</p>';const T0=new Date(a[0].date+'T12:00'),sp=(new Date(a.at(-1).date+'T12:00')-T0)||1,vs=a.map(x=>x.v),lo=Math.min(...vs),hi=Math.max(...vs),g=(hi-lo)||1,X=x=>34+(new Date(x.date+'T12:00')-T0)/sp*254,Y=x=>20+(1-(x.v-lo)/g)*78;
return `<svg class="ch" viewBox="0 0 300 130"><polyline points="${a.map(x=>X(x)+','+Y(x)).join(' ')}"/>${a.map(x=>`<circle cx="${X(x)}" cy="${Y(x)}" r="2.5"/>`).join('')}<text x="2" y="24">${hi}</text><text x="2" y="102">${lo}</text><text x="34" y="124">${a[0].date}</text><text x="288" y="124" text-anchor="end">${a.at(-1).date}</text></svg>`}
function prog(from,to){const rows=[];FIELDS().forEach(m=>{const h=hist(m).filter(x=>x.date>=from&&x.date<=to);if(!h.length)return;const f=h[0].v,l=h.at(-1).v;rows.push(h.length>1?`${m}: ${f} to ${l} ${mu(m)} (${sg(l-f)}, ${sg(f?(l-f)/f*100:0)}%)`:`${m}: ${f} ${mu(m)} (one entry)`)});return rows}
const ck=()=>{const last={};FIELDS().forEach(m=>{const h=hist(m);if(h.length)last[m]=h.at(-1)});return `<section class="card"><h2>Weekly check-in</h2><p class="muted">Each check-in adds new dated entries. Nothing already saved is changed or replaced. Leave a field blank to skip it.</p><input type="date" id="md" value="${today()}">${FIELDS().map(m=>`<div class="row"><label class="grow">${esc(m)}${last[m]?`<small>last: ${last[m].v} ${mu(m)} on ${last[m].date}</small>`:''}</label><input class="mi" type="number" step="0.1" data-m="${esc(m)}" placeholder="${mu(m)}"></div>`).join('')}<div class="row"><input id="cf" placeholder="Custom field, e.g. Neck"><button class="btn" data-act="addf">Add field</button></div><button class="btn fill" data-act="savec">Save check-in</button></section>${HOWTO}`};
const cp=()=>{const ds=mdates();if(!ds.length)return '<p class="muted">Save a check-in to compare dates.</p>';const a=bcmp[0]||ds[0],b=bcmp[1]||ds.at(-1);
return `<div class="row"><button class="btn sm" data-act="cfirst">First vs latest</button><button class="btn sm" data-act="cprev">Previous vs latest</button></div><div class="row"><input type="date" id="bca" value="${a}"><input type="date" id="bcb" value="${b}"></div><section class="card"><div class="li cmp4"><small>Field</small><small>${a}</small><small>${b}</small><small>Change</small></div>${FIELDS().map(m=>{const x=valAt(m,a),y=valAt(m,b);if(!x&&!y)return '';const c=x&&y&&x!==y?`${sg(y.v-x.v)} ${mu(m)} (${sg(x.v?(y.v-x.v)/x.v*100:0)}%)`:x&&y?'same entry':'—',v=(z,d)=>z?z.v+(z.date!==d?`<small>(${z.date})</small>`:''):'—';return `<div class="li cmp4"><small>${esc(m)}</small><b>${v(x,a)}</b><b>${v(y,b)}</b><small>${c}</small></div>`}).join('')}</section><p class="muted">If a field has no entry on a date, the latest earlier entry is used and its date is shown.</p>`};
const tr=()=>{const ms=FIELDS().filter(m=>hist(m).length);if(!ms.length)return '<p class="muted">Save a check-in to see charts.</p>';return ms.map(m=>{const a=hist(m),f=a[0],l=a.at(-1),u=mu(m);return `<section class="card"><b>${esc(m)}: ${l.v} ${u}</b><small>${a.length>1?`First ${f.v} (${f.date}), latest ${l.v} (${l.date}): ${sg(l.v-f.v)} ${u}, ${sg(f.v?(l.v-f.v)/f.v*100:0)}%`:'First entry. Add more check-ins to see change.'}</small>${chart(a)}${a.slice(-3).reverse().map(x=>`<div class="li"><small>${x.date}: ${x.v} ${u}</small><span><button class="x" data-act="edm" data-id="${x.id}" aria-label="Edit">✎</button><button class="x" data-act="delm" data-id="${x.id}" aria-label="Delete">×</button></span></div>`).join('')}</section>`}).join('')};
const rp=()=>{const t=today(),W=[0,1,2,3].map(i=>[addDays(t,-6-7*i),addDays(t,-7*i)]),M=[0,1,2].map(i=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);return iso(d).slice(0,7)}),c=(h,r)=>`<section class="card"><b>${h}</b>${r.length?r.map(x=>`<p>${esc(x)}</p>`).join(''):'<p class="muted">No measurements in this period.</p>'}</section>`;return `<h2>Weekly</h2>${W.map(([a,b])=>c(a+' to '+b,prog(a,b))).join('')}<h2>Monthly</h2>${M.map(m=>c(m,prog(m+'-01',monthEnd(m)))).join('')}`};
const purl=p=>{const u=URL.createObjectURL(p.blob);urls.push(u);return u};
function phv(){urls.forEach(u=>URL.revokeObjectURL(u));urls=[];const ps=[...D.photos].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id),sel=psel.map(id=>ps.find(p=>p.id===id)).filter(Boolean);
return `<section class="card"><h2>Private progress photos</h2><p class="muted">Stored only in this browser. Never uploaded. They are not part of the JSON backup, so keep your own copies of any you care about.</p><div class="row"><input type="date" id="pd" value="${today()}"><label class="btn fill">Add photo<input id="ph" type="file" accept="image/*" hidden></label></div></section>${sel.length===2?`<section class="card"><h2>Comparison</h2><div class="pair">${sel.map(p=>`<div><img src="${purl(p)}" alt="Progress photo"><small>${p.date}</small></div>`).join('')}</div></section>`:'<p class="muted">Tap two photos to compare them side by side.</p>'}<div class="pgrid">${ps.map(p=>`<div class="${psel.includes(p.id)?'sel':''}"><img src="${purl(p)}" data-act="psel" data-id="${p.id}" alt="Photo from ${p.date}"><small>${p.date}<button class="x" data-act="delp" data-id="${p.id}" aria-label="Delete photo">×</button></small></div>`).join('')}</div>`}
async function addPhoto(f){try{const im=await createImageBitmap(f),k=Math.min(1,1000/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);const b=await new Promise(r=>c.toBlob(r,'image/jpeg',.85));await put('photos',{date:N('#pd')||today(),blob:b});await load();toast('Photo saved on this device')}catch{toast('That image could not be read')}}
V.body=()=>`<h1>Measurements</h1><div class="row seg">${[['checkin','Check-in'],['compare','Compare'],['trends','Trends'],['reports','Reports'],['photos','Photos']].map(([k,l])=>`<button class="btn sm ${bv===k?'fill':''}" data-act="bv" data-k="${k}">${l}</button>`).join('')}</div>${{checkin:ck,compare:cp,trends:tr,reports:rp,photos:phv}[bv]()}${bv==='checkin'||bv==='photos'?'':NOTE}`;

// ===== Reminders =====
const RL={water:['Water','Gentle nudges to log a drink.'],workout:['Scheduled workouts','A heads-up at your planned session time.'],measure:['Weekly measurements','A reminder for your check-in.'],nutrition:['Nutrition logging','An evening prompt to log meals.'],sleep:['Sleep schedule','A wind-down reminder.'],summary:['Daily journal and summary','A prompt to review and reflect.'],achv:['Achievements and new PRs','An instant notice when you set a record or reach a session milestone. No schedule needed.']};
const WD=[['Mon',1],['Tue',2],['Wed',3],['Thu',4],['Fri',5],['Sat',6],['Sun',0]];
const canN=()=>'Notification' in window&&'serviceWorker' in navigator,perm=()=>canN()?Notification.permission:'unsupported';
const okT=v=>v.trim()===''||v.split(',').every(x=>ASTRA.mins(x)!=null);
async function setN(path,v){const p=path.split('.'),l=p.pop();let o=D.n;for(const k of p)o=o[k];o[l]=v;await put('profile',D.n)}
async function regPeriodic(){try{const r=await navigator.serviceWorker.ready;if(!('periodicSync' in r))return;const s=await navigator.permissions.query({name:'periodic-background-sync'});if(s.state==='granted')await r.periodicSync.register('astra-check',{minInterval:36e5})}catch{}}
async function notifyAch(b){const n=D.n;if(!n?.r?.achv?.on||perm()!=='granted'||ASTRA.quiet(n,new Date()))return;const m=[];if(b.length)m.push(['New personal record','Nice work on '+b.join(', ')+'.']);if([1,5,10,25,50].includes(D.workouts.length))m.push(['Milestone reached',D.workouts.length+' sessions logged. Steady work adds up.']);try{const r=await navigator.serviceWorker.ready;for(const[t,bd]of m)await r.showNotification('ASTRA: '+t,{body:bd,tag:'astra-ach-'+Date.now(),icon:'assets/icon-192.png',badge:'assets/icon-192.png',data:{url:'#train'}})}catch{}}
const post=async()=>{try{(await navigator.serviceWorker.ready).active?.postMessage('astra-check')}catch{}};
let iaLog;try{iaLog=JSON.parse(localStorage.getItem('astra-ia')||'')}catch{}iaLog??={sent:[]};
function tickN(){if(!D.n?.on)return;if(perm()==='granted')return post();const out=ASTRA.due(D.n,iaLog,new Date());out.forEach(n=>{toast(n.title+': '+n.body);iaLog.sent.push({k:n.key,d:n.d,ts:Date.now()})});if(out.length){iaLog.sent=iaLog.sent.slice(-60);try{localStorage.setItem('astra-ia',JSON.stringify(iaLog))}catch{}}}
setInterval(tickN,3e4);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tickN()});
V.remind=()=>{const n=D.n,p=perm(),st=matchMedia('(display-mode: standalone)').matches,ps=typeof ServiceWorkerRegistration!=='undefined'&&'periodicSync' in ServiceWorkerRegistration.prototype;
return `<h1>Reminders</h1><section class="card"><h2>Notifications</h2><p class="muted">${p==='granted'?'Notifications are allowed on this device.':p==='denied'?'Notifications are blocked. Allow them for this app in your Android settings. Until then, reminders show inside the app while it is open.':p==='unsupported'?'This browser cannot show notifications, so reminders appear inside the app while it is open.':'Reminders can nudge you at times you choose, such as a water break or your weekly check-in. Your schedule stays on this device, and the browser only asks for permission after you tap the button below.'}</p>${p==='default'?'<button class="btn fill" data-act="nperm">Turn on notifications</button>':'<label class="wu"><input type="checkbox" data-n="on" '+(n.on?'checked':'')+'>Reminders enabled</label>'}${p==='granted'?'<button class="btn" data-act="ntest">Send a test notification</button>':''}<small>Installed as an app: ${st?'yes':'no. Installing improves your chances of background delivery.'} Background wake-ups: ${ps?'available in this browser (best effort)':'not available in this browser'}.</small></section>
<section class="card"><h2>Quiet hours and limits</h2><label class="wu"><input type="checkbox" data-n="quiet.on" ${n.quiet.on?'checked':''}>Quiet hours (no notifications)</label><div class="row"><input type="time" data-n="quiet.from" value="${n.quiet.from}"><input type="time" data-n="quiet.to" value="${n.quiet.to}"></div><div class="row"><label class="grow"><small>Max per day</small><input type="number" min="1" max="20" data-n="max" value="${n.max}"></label><label class="grow"><small>Min gap, minutes</small><input type="number" min="0" max="240" data-n="gap" value="${n.gap}"></label></div></section>
${Object.entries(RL).map(([k,[t,d]])=>`<section class="card"><label class="wu"><input type="checkbox" data-n="r.${k}.on" ${n.r[k].on?'checked':''}><b>${t}</b></label><p class="muted">${d}</p>${k==='achv'?'':`<details><summary>Schedule by weekday</summary><div class="row"><span class="dn">All days</span><input data-nall="${k}" placeholder="e.g. 09:00, 13:30"></div>${WD.map(([l,i])=>`<div class="row"><span class="dn">${l}</span><input data-n="r.${k}.days.${i}" value="${esc(n.r[k].days[i])}" placeholder="none"></div>`).join('')}</details>`}</section>`).join('')}
<section class="card"><h2>How delivery works</h2><ul class="tips"><li><b>Works reliably:</b> achievement and PR notifications, because your own action in the app triggers them. The test button too.</li><li><b>Works while the app is open or recently used:</b> all scheduled reminders. The app checks every 30 seconds, and a reminder is still shown if you reopen the app within 45 minutes of its time.</li><li><b>Best effort only:</b> in an installed Android Chrome app, the browser may wake ASTRA in the background now and then. It decides when, usually infrequently, so this will not hit exact times.</li><li><b>Needs extra infrastructure:</b> on-time scheduled notifications while the app is fully closed require Web Push: a small server that stores your push subscription and schedule and sends the pushes. That is an optional second phase. ASTRA does not need it for anything else.</li></ul><p class="muted">Quiet hours and limits skip a reminder rather than delay it. Messages are neutral by design, and nothing is sent for missed goals.</p></section>`};
Object.assign(A,{bv:b=>{bv=b.dataset.k},cfirst:()=>{const d=mdates();bcmp=[d[0],d.at(-1)]},cprev:()=>{const d=mdates();bcmp=[d.at(-2)||d[0],d.at(-1)]},
savec:async()=>{const d=N('#md')||today();let c=0;for(const i of document.querySelectorAll('.mi'))if(i.value!==''&&+i.value>0){await put('measurements',{date:d,m:i.dataset.m,v:+i.value});c++}if(!c)return toast('Enter at least one value');await load();toast(c+' measurement'+(c>1?'s':'')+' saved')},
addf:async()=>{const n=N('#cf').trim();if(n&&!FIELDS().includes(n)){D.me.fields=[...(D.me.fields||[]),n];await put('profile',D.me);await load()}},
edm:async b=>{const x=D.measurements.find(m=>m.id===ID(b)),v=prompt('Edit '+x.m+' on '+x.date,x.v);if(v!==null&&+v>0){await put('measurements',{...x,v:+v});await load()}},
psel:b=>{const id=ID(b);psel=psel.includes(id)?psel.filter(x=>x!==id):[...psel.slice(-1),id]},delp:async b=>{if(confirm('Delete this photo from this device?')){await rm('photos',ID(b));psel=psel.filter(x=>x!==ID(b));await load()}},
nperm:async()=>{try{const p=await Notification.requestPermission();if(p==='granted'){D.n.on=true;await put('profile',D.n);await regPeriodic();toast('Notifications are on')}else toast('No problem. Reminders will still appear inside the app while it is open.')}catch{toast('Permission could not be requested here')}},
ntest:async()=>{try{const r=await navigator.serviceWorker.ready;await r.showNotification('ASTRA test',{body:'If you can read this, notifications work on this device.',tag:'astra-test',icon:'assets/icon-192.png',badge:'assets/icon-192.png',data:{url:'#remind'}})}catch{toast('The test notification could not be shown')}}});
